import{_ as e,o,c as r,a2 as a}from"./chunks/framework.YT-FC_Xx.js";const p=JSON.parse('{"title":"状态页","description":"","frontmatter":{},"headers":[],"relativePath":"guide/status-page.md","filePath":"guide/status-page.md","lastUpdated":1794151265000}'),d={name:"guide/status-page.md"};function s(n,t,l,i,g,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="状态页" tabindex="-1">状态页 <a class="header-anchor" href="#状态页" aria-label="Permalink to &quot;状态页&quot;">​</a></h1><p>状态页是一个不用登录就能打开的页面，地址是 <code>面板地址/status/</code>。它展示每台服务器是否在线、近 30 天的可用率、CPU / 内存 / Swap / 磁盘、负载、TCP / UDP 连接数、实时网速和本月流量，以及到各测试点的延迟和回程线路，适合发给用户或挂在群公告里。</p><p>状态页<strong>不会</strong>显示服务器 IP、端口、密钥、用户、节点和协议，也不显示系统版本、内核版本和 agent 版本。回程只显示线路名（例如 CN2 GIA、9929、CMI），不显示经过的每一跳。</p><h2 id="开启" tabindex="-1">开启 <a class="header-anchor" href="#开启" aria-label="Permalink to &quot;开启&quot;">​</a></h2><p>在 <strong>设置 → 状态页</strong> 打开 <strong>开启状态页</strong> 后保存，登录页下方会出现“查看服务器状态”入口。默认是关闭的，关闭时访问 <code>/status/</code> 只会看到“状态页未开启”。</p><table tabindex="0"><thead><tr><th>设置</th><th>说明</th></tr></thead><tbody><tr><td>标题</td><td>留空时使用应用名称</td></tr><tr><td>显示网速和流量</td><td>默认开启；关闭后不显示实时上下行速度和本月流量，详情页也没有网速图</td></tr><tr><td>显示系统信息</td><td>默认关闭；开启后显示每台服务器的系统、架构、虚拟化方式和 CPU 型号。内核版本始终不公开</td></tr><tr><td>显示到期日</td><td>默认关闭；开启后，设了到期时间的服务器会显示到期日期</td></tr><tr><td>显示价格</td><td>默认关闭；开启后，填了价格的服务器显示价格和付款周期，例如 <code>¥151.2/年</code></td></tr><tr><td>分组方式</td><td><strong>自动</strong>（默认）：有服务器填了分组就按分组，否则按地区；<strong>按分组</strong>：没填分组的归入「其他」；<strong>按地区</strong></td></tr><tr><td>显示哪些服务器</td><td>取消勾选的服务器不会出现在状态页上；也可以在 <strong>服务器 → 编辑 → 公开显示</strong> 里单独开关</td></tr></tbody></table><p>每台服务器显示所在地区的国旗（Windows 没有国旗表情，状态页会自动加载面板自带的国旗字体）。服务器按分组或地区分段显示，列表上方可以按分组筛选，也可以输入名称、分组或备注筛选。分组在 <strong>服务器 → 编辑 → 分组</strong> 里填，地区怎么来的见下面的 <a href="#地区">地区</a>。</p><p>服务器的 <strong>公开备注</strong> 显示在名称下面（<strong>私有备注</strong> 只有管理员看得到）；设了 <strong>每月额度</strong> 时，卡片上多一条额度进度条，列表的本月流量下面也有，见 <a href="./servers#流量额度与校正">服务器 → 流量额度</a>。</p><p>服务器默认以卡片显示，右上角可以切换成 <strong>列表</strong>（表格），浏览器会记住选择。右上角的月亮 / 太阳按钮切换深色和浅色。</p><p>延迟和回程来自 <strong>设置 → 延迟测试点</strong>，卡片上最多显示 3 个测试点（服务器设置了固定显示的测试点时用那几个）。回程每天检测一次，检测过才显示；双栈服务器的 IPv6 回程与 IPv4 不同时，后面多一个 <code>v6</code> 标签。见 <a href="./latency">延迟与回程</a>。</p><h2 id="地区" tabindex="-1">地区 <a class="header-anchor" href="#地区" aria-label="Permalink to &quot;地区&quot;">​</a></h2><p>面板按服务器的地址自动识别所在国家或地区：依次看 <strong>IPv4 地址</strong>、<strong>域名/主机名</strong>（先解析成 IP）和 <strong>IPv6 地址</strong>，用第一个公网地址查询。内网地址（例如家里的 NAS 填的 <code>192.168.x.x</code>）查不出地区。识别结果在 <strong>服务器</strong> 列表名称前显示国旗。</p><p>识别不对或查不出时，在 <strong>服务器 → 编辑 → 地区</strong> 里手动选择；选了的以手选为准，选回 <strong>自动识别</strong> 恢复自动。服务器名称本来就以国旗 emoji 开头（例如 <code>🇭🇰 香港 HKT</code>）时，状态页仍然用名称里的旗帜。</p><p>识别用的是 <a href="https://db-ip.com" target="_blank" rel="noreferrer">DB-IP</a> 免费的国家数据库（IP to Country Lite，CC BY 4.0）。面板第一次启动时把它下载到数据目录的 <code>geoip/</code> 下（约 4 MB），之后每月更新一次；下载不了时只是不能自动识别，手动选择不受影响。数据库只在面板本地查询，不会把服务器地址发给第三方。状态页只公开国家代码，不公开地址。</p><table tabindex="0"><thead><tr><th>环境变量 <code>GEOIP_COUNTRY_DB</code></th><th>说明</th></tr></thead><tbody><tr><td>不设置（默认）</td><td>自动下载并每月更新 DB-IP 国家库</td></tr><tr><td>文件路径</td><td>使用你自己放的 MaxMind 格式（<code>.mmdb</code>）国家库，面板不下载也不覆盖</td></tr><tr><td><code>off</code></td><td>关闭自动识别，只用手动选择的地区</td></tr></tbody></table><h2 id="服务器详情" tabindex="-1">服务器详情 <a class="header-anchor" href="#服务器详情" aria-label="Permalink to &quot;服务器详情&quot;">​</a></h2><p>点服务器卡片（或列表的一行）进入详情页 <code>面板地址/status/node/&lt;序号&gt;</code>，顶部是当前的 CPU、内存、Swap、磁盘、负载、连接数、网速、本月流量和到期日，以及各测试点的延迟、丢包和回程；下面可以看近 1 小时、6 小时、24 小时、7 天的历史： CPU / 内存 / Swap / 磁盘使用率、网速、负载、TCP / UDP 连接数和进程数，以及各测试点的延迟（断开处为超时）。 每个点是一段时间内的平均值（1 小时为 10 秒，7 天约 28 分钟）。</p><ul><li>历史能看多久取决于 <strong>设置 → 服务器与监控</strong> 里的监控数据保留天数（默认 7 天）。</li><li>序号是服务器在状态页上的位置，不是面板里的编号；隐藏的服务器没有详情页。</li><li>Swap、进程数以及系统信息需要节点 agent 3.9.0 及以上；旧 agent 照常工作，只是不显示这几项。</li></ul><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><p>状态页的外观由<strong>主题</strong>决定，在 <strong>设置 → 状态页 → 主题</strong> 里管理，操作立即生效，不需要点保存：</p><ul><li><strong>FLYX 默认</strong>：内置主题，随面板一起升级，不能删除。</li><li><strong>从 GitHub 安装</strong>：填主题仓库地址（如 <code>https://github.com/作者/仓库</code>），面板下载该仓库最新 release 里的 <code>theme.tar.gz</code>。</li><li><strong>上传 theme.tar.gz</strong>：面板连不上 GitHub 时，先在电脑上下载主题包再上传，最大 32 MiB。</li><li><strong>使用</strong>：切换到这个主题；<strong>检查更新</strong>：有新 release 时更新到最新版本；<strong>删除</strong>：正在使用的主题被删除后自动换回内置主题，它的设置也一并删除。</li><li><strong>设置</strong>：主题提供了可调整的选项时才显示（内置主题暂时没有）。只保存改过的项，<strong>恢复默认</strong> 清空全部；保存后状态页刷新即生效。设置对访客公开，不要填写密码一类的内容。</li></ul><p>安装的主题保存在面板数据目录的 <code>themes/</code> 下（Docker 部署即 <code>sqlite_data</code> 卷），升级或重装面板不会丢失。</p><div class="warning custom-block"><p class="custom-block-title">只安装信任的主题</p><p>主题是运行在面板域名下的网页，能读到同一浏览器里的面板登录状态。只安装你信任的作者发布的主题。</p></div><p>monitor 的主题不能直接安装：FLYX 主题使用 FLYX 的状态接口，需要按 <a href="./status-theme-dev">主题开发</a> 适配。</p><h2 id="可用率怎么算" tabindex="-1">可用率怎么算 <a class="header-anchor" href="#可用率怎么算" aria-label="Permalink to &quot;可用率怎么算&quot;">​</a></h2><p>面板每分钟检查一次每台服务器是否在线，记录保留 31 天。</p><ul><li><strong>24 小时 / 30 天</strong>：这段时间内服务器在线的比例。</li><li><strong>每天一格</strong>：离线不超过 5 分钟为绿色，5–30 分钟为橙色，超过 30 分钟为红色，没有记录为灰色。一次重启或很短的断线不会让当天变红。</li></ul><p>可用率从升级到带状态页的版本后才开始记录，之前的日子显示为灰色。日期按面板服务器的时区划分（安装脚本默认 <code>Asia/Shanghai</code>）。</p><p>页面每 10 秒自动刷新一次。实时数据（CPU、内存、网速等）来自 agent 上报，超过 3 分钟没有上报就不再显示。</p><p>CPU 核心数和内存、磁盘的已用 / 总容量需要把 agent 升级到同一版本或更新版本；旧 agent 照常工作，只是不显示这几项。磁盘统计的是根分区 <code>/</code>。容器里运行的 agent 读到的通常是宿主机的核心数和内存，不是容器的限制。</p><h2 id="延迟" tabindex="-1">延迟 <a class="header-anchor" href="#延迟" aria-label="Permalink to &quot;延迟&quot;">​</a></h2><p>服务器设置了 <a href="./latency">延迟测试点</a> 时，卡片上显示最多 3 个测试点近 1 小时的延迟和丢包（优先显示固定的测试点）。只显示测试点的名称，不显示测试地址和错误信息。</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><ul><li>状态页只能读取，没有任何会改动面板的操作；关闭后接口只返回“状态页未开启”。</li><li>接口只接受 GET / HEAD 请求，所有访客拿到的是同一份缓存好的结果，每 5 秒最多重新查询一次数据库。大量请求的开销和访问静态文件差不多，刷新不会拖慢面板。</li><li>响应带 <code>Cache-Control: public, max-age=5</code>，面板放在 Cloudflare 等 CDN 后面时，重复请求大多由 CDN 挡下。</li><li>服务器名称会原样公开，不要在里面写 IP 或敏感信息；不想公开的服务器在“显示哪些服务器”里取消勾选。</li></ul>',34)])])}const u=e(d,[["render",s]]);export{p as __pageData,u as default};
